    Bug 1826762 - In unified folder mode, display the folder name if it isn't the localised name. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D272353

diff --git a/mail/base/content/about3Pane.js b/mail/base/content/about3Pane.js
index 9958bae17eb..76e2c64ca21 100644
--- a/mail/base/content/about3Pane.js
+++ b/mail/base/content/about3Pane.js
@@ -1052,10 +1052,16 @@ var folderPane = {
       _addSearchedFolder(folderType, parentFolder, childFolder) {
         if (folderType.flag & childFolder.flags) {
           // The folder has the flag for this type.
+          const smartFolder = this._smartMailbox.getSmartFolder(
+            folderType.name
+          );
           const folderRow = folderPane._createFolderRow(
             this.name,
             childFolder,
-            "server"
+            // If the name is not localised, display the name and server name.
+            childFolder.localizedName == smartFolder.localizedName
+              ? "server"
+              : "both"
           );
           folderPane._insertInServerOrder(folderType.list, folderRow);
           return;
diff --git a/mail/base/test/browser/browser_folderTreeQuirks.js b/mail/base/test/browser/browser_folderTreeQuirks.js
index 4ef2821756e..e32721dae80 100644
--- a/mail/base/test/browser/browser_folderTreeQuirks.js
